import sys

def main():
    # Read first line and parse array
    line1 = sys.stdin.readline().strip()
    if line1 == "":
        print(-1)
        return
    arr = list(map(int, line1.split()))

    # Read second line and parse target
    line2 = sys.stdin.readline().strip()
    if line2 == "":
        print(-1)
        return
    target = int(line2)

    # Find all indices using linear search
    indices = []
    for i in range(len(arr)):
        if arr[i] == target:
            indices.append(i)

    # Output result
    if len(indices) == 0:
        print(-1)
    else:
        print(' '.join(map(str, indices)))

if __name__ == "__main__":
    main()
